"""Report evidence readiness without pretending downstream states are known."""
import json,html,numpy as np
from jump_rig import ROOT

def main():
    out=ROOT/'results/jump_contact_visualization';v=json.loads((out/'validation.json').read_text());ext=json.loads((out/'external_reference_review.json').read_text());sens=json.loads((out/'calf_allocation_sensitivity.json').read_text());spec=json.loads((ROOT/'scenarios/foundation_validation.json').read_text());z=np.load(ROOT/'results/contact_jump_scapula/600hz/tensions.npz');keys=set(z.files)
    cases={r['case']:r for r in sens['cases']};base=cases['baseline']['sides'][0]['peak_N'];changes=[]
    for name,row in cases.items():
        if row['status']=='solved':changes.append(dict(case=name,right_calf_peak_N=row['sides'][0]['peak_N'],difference_percent=100*(row['sides'][0]['peak_N']/base-1)))
    states={'muscle_tendon_force': 'force_N' in keys,'selected_active_tension': 'active_force_N' in keys,'muscle_tendon_path_length':'length_m' in keys,'muscle_tendon_path_velocity':'path_velocity_m_s' in keys,'activation_or_excitation':False,'contractile_fiber_length_velocity':False,'calibrated_capacity_reference':False,'validated_fatigue_recovery_states':False,'validated_metabolic_or_oxidative_states':False}
    status=dict(status='foundation_under_validation',downstream_prediction_ready=False,numerical_mechanics_passed=v['all_mechanics_gates_pass'],muscle_time_step_sensitivity_passed=v['significant_force_groups_converged'],external_reference_validation=ext['status'],available_states=states,calf_controlled_sensitivity=changes,main_diagnostic_inference='At fixed motion, COP and muscle geometry, removing passive floors or the temporal penalty changes the calf peak by less than 1%. These tested assumptions alone do not explain the large peak. Prioritize experimental replay, contact/COP and anatomical path checks; not a proof of a single root cause.',next_validation_step='Measured low-complexity replay before new controller-designed jumps or physiological predictions.',future_models=spec['candidate_models'],force_cap_added=False,canonical_force_solution_modified=False)
    assert status['external_reference_validation']=='external_validation_not_passed'
    measured=ROOT/'results/measured_cmj/summary.json'
    if measured.exists():
        mr=json.loads(measured.read_text());status['measured_replay']=dict(status=mr['status'],trials=len(mr['trials']),basic_fixtures=mr['basic_tests_passed'],model_scope=mr['model_scope'],report='../measured_cmj/index.html',muscle_force_validation_passed=False)
    (out/'foundation_readiness.json').write_text(json.dumps(status,indent=2))
    table=''.join(f'<tr><td>{html.escape(c["case"].replace("_"," "))}</td><td>{c["right_calf_peak_N"]:.0f}</td><td>{c["difference_percent"]:+.2f}%</td></tr>' for c in changes)
    state_table=''.join(f'<tr><td>{html.escape(key.replace("_"," "))}</td><td>{"Present as conditional model output" if present else "Not established"}</td></tr>' for key,present in states.items())
    page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Foundation readiness</title><style>body{{max-width:1000px;margin:30px auto;padding:20px;background:#0d1726;color:#edf3fb;font:18px/1.65 system-ui}}a{{color:#8ce2d5}}strong{{color:#f0b74e}}table{{border-collapse:collapse;font-size:16px}}td,th{{border:1px solid #465e76;padding:9px}}.scroll{{overflow:auto}}</style><a href="index.html">Viewer</a> · <a href="reference_review.html">External evidence</a><h1>Build a validated mechanical foundation first</h1><p><strong>Current state: diagnostic mechanics; not ready for predictive fatigue or metabolic strategy claims.</strong> A bodyweight multiplier is a task-dependent comparison, not a force cap or a target for fitting.</p><h2>Controlled calf-load diagnosis</h2><p>Motion, ground forces/COP, muscle paths, joint demand and the shoulder cone were held fixed. Only the named model assumption was changed. No canonical force values were modified.</p><div class="scroll"><table><tr><th>Case</th><th>Right calf peak [N]</th><th>Change</th></tr>{table}</table></div><p>Removing passive floors or the temporal term changes this peak by less than 1%. These assumptions alone do not explain its magnitude. The cost-reference variants change numerical force-sharing weights, not actual muscle size. Zero-passive variants are diagnostic experiments, not proposed physiological corrections.</p><h2>Validation sequence</h2><ol>{''.join('<li><strong>'+html.escape(x['id'].replace('_',' '))+'</strong>: '+html.escape(x['purpose'])+'</li>' for x in spec['validation_sequence'])}</ol><p>Use matching mass, measured motion, external load point, GRF/COP and the same tissue-force definition. Predeclare acceptable errors from measurement uncertainty and intended use. Reserve held-out trials for validation rather than fitting and checking the same curve.</p><h2>What the current data contain</h2><div class="scroll"><table><tr><th>State</th><th>Availability</th></tr>{state_table}</table></div><p>Reference-normalized force is not activation. A capacity reference is needed to define relative fatigue demand even when mechanical force is allowed to exceed it. That reference need not clamp a prescribed motion.</p><h2>Later physiological models</h2><p><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC6092960/">3CC-r</a> is a candidate for fatigue/recovery, initially in the intermittent isometric joint-load scope in which it was studied. Dynamic barbell transfer and individual muscle fatigue require separate evidence.</p><p><a href="https://opensimconfluence.atlassian.net/wiki/spaces/OpenSim/pages/53089593">OpenSim Umberger/Bhargava probes</a> are candidate metabolic-energy models. They need muscle-state assumptions; tension or external mechanical work alone cannot supply metabolic demand. Oxidative ATP/oxygen dynamics and oxidative stress are different extensions and have not been defined here.</p><p>Future comparisons may include grip, limb proportions, load, tempo and rest intervals, but conclusions need uncertainty and validation for the task range. They are virtual scenario comparisons, not personalized training prescriptions.</p><p><a href="foundation_readiness.json">Readiness data</a> · <a href="calf_allocation_sensitivity.json">Controlled comparison data</a> · <a href="../../scenarios/foundation_validation.json">Validation contract</a></p></html>'''
    if measured.exists():page=page.replace('<h2>Controlled calf-load diagnosis</h2>','<h2>Measured replay started</h2><p><a href="../measured_cmj/index.html">Three measured CMJ trials, reference-model replay and force comparison</a>. This is a separately scaled reference model; the presentation model and individual muscle tensions remain unvalidated.</p><h2>Controlled calf-load diagnosis</h2>')
    (out/'foundation_readiness.html').write_text(page,encoding='utf-8')
    print(json.dumps(dict(status=status['status'],downstream_prediction_ready=False,calf_controlled_sensitivity=changes)),flush=True)

if __name__=='__main__':main()
